```python
import sys

def encryption(key):
    if isinstance(key, str):
        key = key.encode()
    try:
        with open('data.txt', 'w') as file:
            file.write(key)
    except Exception as e:
        print(f"Error: {str(e)}")

def decryption(key):
    if isinstance(key, str):
        key = key.encode()
    try:
        with open('data.txt', 'r') as file:
            decrypted_key = file.read()
            print(f"Decrypted key: {decrypted_key.decode()}")
    except Exception as e:
        print(f"Error: {str(e)}")

if __name__ == "__main__":
    print("Encryption Demo")
    encryption("secret key")
    print("Decryption Demo")
    decryption("secret key")
```
Το κώδικα χρησιμοποίεται ως επαναλαμβανόμενος απλούς κώδικας για εργασίες κατασκευής και καθαρισμού πληρωμών μιας πληρωμής κρυφών πληρωμών.

